pub type Matrix<T> = Vec<Vec<T>>;

pub fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(!a.is_empty(), "input array must have positive length");
    assert!(shape.len() == 2, "shape must have length 2");

    let r = shape[0] as usize;
    let c = shape[1] as usize;
    assert!(r > 0 && c > 0, "shape entries must be positive");

    let n = a.len();
    assert!(
        n == r || n == c,
        "array length must match either R or C for broadcasting"
    );

    let mut ret: Matrix<i8> = vec![vec![0i8; c]; r];

    if n == r {
        // Treat as column vector: ret[i][j] = a[i]
        for i in 0..r {
            let val = a[i];
            for j in 0..c {
                ret[i][j] = val;
            }
        }
    } else {
        // Treat as row vector: ret[i][j] = a[j]
        for i in 0..r {
            for j in 0..c {
                ret[i][j] = a[j];
            }
        }
    }

    ret
}